function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function elHTML(e, interactive=false){return `<div ${interactive?`tabindex="0" role="button" aria-label="${esc(e.type==='text'?e.text:'図形')}" data-element="${e.id}"`:''} class="slide-element ${e.type} ${selected===e.id&&interactive?'selected':''} ${e.locked?'locked':''} ${interactive&&highlight.includes(e.id)?'explained':''}" style="left:${e.x}px;top:${e.y}px;width:${e.w}px;height:${e.h}px;${e.type==='text'?`font-size:${e.size}px;color:${hex(e.color)};font-weight:${e.bold?700:400}`:`background:${hex(e.fill)};border-radius:${e.radius||0}px`}">${e.type==='text'?esc(e.text):''}${interactive&&e.locked?'<span class="lock-mark">固定</span>':''}</div>`;}
function rationaleHTML(v){return `<div class="rationale"><span class="eyebrow">なぜ、このデザインか</span><ol>${v.rationale.map((x,i)=>`<li><button data-why="${i}" ${x.ids.length?'':'class="no-target"'}><strong>${esc(x.what)}</strong><span>${esc(x.why)}</span></button></li>`).join('')}</ol></div>`;}
