function issuesHTML(issues){return issues.map(x=>`<div class="lint"><strong>⚠ ${esc(x.rule)}</strong><p>${esc(x.why)}</p></div>`).join('');}
function slideHTML(scene,interactive=false){return `<div class="slide-stage ${interactive?'editable':''}" style="background:${hex(scene.bg)}">${scene.elements.map(e=>elHTML(e,interactive)).join('')}</div>`;}
