 $('#undo').onclick=()=>{if(!history.length)return;future.push(clone(state));state=history.pop();selected=null;preview=null;persist();render();};
 $('#redo').onclick=()=>{if(!future.length)return;history.push(clone(state));state=future.pop();selected=null;preview=null;persist();render();};
 ['audience','goal'].forEach(key=>{const input=$('#'+key);if(input)input.onchange=()=>commit(()=>state.brief[key]=input.value);});
 $('#export').onclick=showExport;$('#present').onclick=()=>{openModal(`<div class="presentation-preview slide-frame">${slideHTML(state.scenes[state.page])}</div><div class="modal-actions"><span>${pad(state.page+1)} / ${pad(n)}</span><button data-close>閉じる</button></div>`);fitSlides();};
