function showExport(){openModal(`<div class="modal-heading"><div><span class="eyebrow">KEEP CREATING</span><h2>Google Slidesで、続きを。</h2></div><button data-close aria-label="閉じる">×</button></div><p class="muted">編集中の${n}枚を、新しいGoogle Slidesに書き出します。文字と図形は個別に編集できます。フォントや改行、図形の角丸は変わる場合があります。</p><div class="connection-status">○ Google連携は未設定です</div><p class="small">初回はGoogle CloudのOAuthクライアントIDが必要です。設定方法はREADMEに記載しています。</p><label class="field-label" for="client-id">OAuth クライアントID</label><input id="client-id" placeholder="…apps.googleusercontent.com" value="${esc(localStorage.getItem('slipper.clientId')||'')}"><p class="muted small">接続後、Googleの許可画面が開きます。元の資料は上書きしません。</p><div id="export-status" role="status"></div><div class="modal-actions"><button id="download">JSONで保存</button><button class="primary" id="connect" ${exportBusy?'disabled':''}>Googleに接続して新規作成 ↗</button></div><details class="import-details"><summary>保存したJSONを読み込む</summary><input id="import-file" type="file" accept="application/json,.json"><p class="muted small">現在の${n}枚を置き換えます。取り消し可能です。</p></details>`);$('#download').onclick=()=>{download();toast('編集データを保存しました');};$('#connect').onclick=connectGoogle;$('#import-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2e6)throw Error('ファイルが大きすぎます');const data=JSON.parse(await file.text());validateImport(data);commit(()=>{state={page:0,scenes:data.scenes,choices:data.choices,brief:data.brief};selected=null;});$('#modal').close();toast('編集データを読み込みました');}catch(error){$('#export-status').textContent='読み込めません: '+error.message;}};}
function validateImport(data){
 if(data.version!==2||!Array.isArray(data.scenes)||data.scenes.length!==n||!Array.isArray(data.choices)||data.choices.length!==n||data.choices.some((i,k)=>!Number.isInteger(i)||i<0||i>=pages[k].variants.length)||typeof data.brief?.audience!=='string'||typeof data.brief?.goal!=='string')throw Error('Slipperの保存ファイルを選んでください');
 const color=v=>Object.hasOwn(deck.colors,v);
 for(const s of data.scenes){if(!color(s.bg)||!Array.isArray(s.elements)||s.elements.length>100)throw Error('不正なスライドです');const ids=new Set();for(const e of s.elements){if(!/^[\w-]+$/.test(e.id)||ids.has(e.id)||!['text','box'].includes(e.type)||!['x','y','w','h'].every(k=>Number.isFinite(e[k]))||e.x<0||e.y<0||e.w<1||e.h<1||e.x+e.w>W+1||e.y+e.h>H+1)throw Error('不正な要素です');ids.add(e.id);if(e.type==='text'&&(typeof e.text!=='string'||e.text.length>10000||!Number.isFinite(e.size)||e.size<1||e.size>120||!color(e.color)))throw Error('不正な文字です');if(e.type==='box'&&(!color(e.fill)||(e.radius!==undefined&&(!Number.isFinite(e.radius)||e.radius<0))))throw Error('不正な図形です');}}
}
let gisReady;
function loadGIS(){if(window.google?.accounts?.oauth2)return Promise.resolve();if(gisReady)return gisReady;gisReady=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.onload=resolve;script.onerror=()=>{gisReady=null;reject(Error('Googleの認証ライブラリを読み込めません。通信を確認して再試行してください。'));};document.head.append(script);});return gisReady;}
async function connectGoogle(){
 const id=$('#client-id').value.trim(),status=$('#export-status');if(!/^[\w.-]+\.apps\.googleusercontent\.com$/.test(id)){status.textContent='有効なOAuthクライアントIDを入力してください。';return;}
 localStorage.setItem('slipper.clientId',id);exportBusy=true;$('#connect').disabled=true;status.textContent='Google認証を準備しています…';
 try{await loadGIS();status.textContent='認証の準備ができました。もう一度押すとGoogleの許可画面を開きます。';$('#connect').textContent='認証して新しい資料を作成';$('#connect').disabled=false;exportBusy=false;
 $('#connect').onclick=()=>{exportBusy=true;$('#connect').disabled=true;const client=google.accounts.oauth2.initTokenClient({client_id:id,scope:'https://www.googleapis.com/auth/drive.file',callback:async response=>{if(response.error){finishError(response.error);return;}if(!google.accounts.oauth2.hasGrantedAllScopes(response,'https://www.googleapis.com/auth/drive.file')){finishError('資料を作成する権限が許可されていません');return;}await exportGoogle(response.access_token);},error_callback:error=>finishError(error.type==='popup_closed'?'認証をキャンセルしました。':error.type)});client.requestAccessToken();};
 }catch(error){finishError(error.message);}
}
function finishError(message){exportBusy=false;if($('#connect'))$('#connect').disabled=false;if($('#export-status'))$('#export-status').textContent=message;}
async function exportGoogle(token){
 let createdId;const status=$('#export-status'),scenes=clone(state.scenes);
 async function api(path,body){const response=await fetch('https://slides.googleapis.com/v1/presentations'+path,{method:'POST',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw Error(data.error?.message||`Google API: ${response.status}`);return data;}
 try{status.textContent='新しい資料を作成しています…';const created=await api('',{title:`${deck.title} — Slipper`});createdId=created.presentationId;await api('/'+createdId+':batchUpdate',{requests:toGoogleRequests(scenes,deck.colors,'slipper_'+Date.now())});status.innerHTML=`<a class="success-link" href="https://docs.google.com/presentation/d/${encodeURIComponent(createdId)}/edit" target="_blank" rel="noopener noreferrer">${n}枚を書き出しました。Google Slidesで開く ↗</a>`;$('#connect').textContent='書き出し完了';exportBusy=false;toast('Google Slidesに新しい資料を作成しました');}
 catch(error){finishError('書き出しに失敗しました: '+error.message);if(createdId){const a=document.createElement('a');a.href=`https://docs.google.com/presentation/d/${encodeURIComponent(createdId)}/edit`;a.target='_blank';a.rel='noopener noreferrer';a.textContent='作成済みの空の資料を確認 ↗';status.append(document.createElement('br'),a);}}
 finally{token=null;}
}
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='z'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('#modal').open){e.preventDefault();$(e.shiftKey?'#redo':'#undo').click();}});
render();
